  if(w.metrics.occupancy>0||w.metrics['release:tailRatePerKey']>0)assert.notEqual(w.tag,'break');
  if(w.structurallyEmpty){assert.equal(w.tag,'break');assert.equal(w.aggregationWeight,0);}
 }
